const qs = [
"rg -n \"RunOnce|Refresh|refresh|stale|scheduler|Schedule|webhook|Webhook|Post\\(\" internal server store --glob '*.go'",
"rg -n \"type .* interface|type .* struct|New.*Markdown|markdown\\.\" internal server --glob '*.go'",
"rg -n \"visibility|Visibility\" server/router/api/v1 --glob '*.go'",
"rg -n \"mysql|NewStore|Driver|driver\" store server --glob '*.go' | head -250",
"rg -n \"graphql|GraphQL|rate.?limit|redis|rabbit|nats|cron|cleanup\" --glob '!web/**' --glob '*.go' --glob '*.proto' --glob '*.yaml' --glob '*.yml'"
];
const rs = await Promise.all(qs.map(cmd=>tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:15000})));
rs.forEach((r,i)=>{text(`---${i+1}---`); text(r.output)});

